const assert = require('node:assert/strict');

const { ProfileService } = require('../.build/service');
const { parseProfile } = require('../.build/parser');

const throwsInvalid = (fn, label) => {
  assert.throws(fn, (err) => err instanceof Error && err.message === 'invalid profile', label);
};

// Validated no-op / keep behavior
{
  const service = new ProfileService({ displayName: 'before', tags: ['old'] });
  const result = service.patch({});
  assert.strictEqual(result, service.profile);
  assert.deepEqual(result, { displayName: 'before', tags: ['old'] });
}

// displayName trimming and bounds
{
  const service = new ProfileService({ displayName: 'before', tags: ['old'] });
  assert.deepEqual(service.patch({ displayName: '  after  ' }), { displayName: 'after', tags: ['old'] });
  assert.deepEqual(service.patch({ displayName: null }), { displayName: null, tags: ['old'] });
  assert.deepEqual(service.patch({ displayName: 'a'.repeat(40) }), { displayName: 'a'.repeat(40), tags: ['old'] });
  assert.deepEqual(service.patch({ displayName: 'b' }), { displayName: 'b', tags: ['old'] });
  throwsInvalid(() => service.patch({ displayName: '' }), 'empty displayName');
  throwsInvalid(() => service.patch({ displayName: '   ' }), 'blank displayName');
  throwsInvalid(() => service.patch({ displayName: 'a'.repeat(41) }), 'long displayName');
  throwsInvalid(() => service.patch({ displayName: 42 }), 'numeric displayName');
  throwsInvalid(() => service.patch({ displayName: true }), 'boolean displayName');
  throwsInvalid(() => service.patch({ displayName: undefined }), 'undefined displayName');
  throwsInvalid(() => service.patch({ displayName: ['x'] }), 'array displayName');
  throwsInvalid(() => service.patch({ displayName: { value: 'x' } }), 'object displayName');
  assert.deepEqual(service.profile, { displayName: 'b', tags: ['old'] });
}

// tags trimming, clearing, bounds, distinctness
{
  const service = new ProfileService({ displayName: 'x', tags: ['old'] });
  const cleared = service.patch({ tags: null });
  assert.deepEqual(cleared, { displayName: 'x', tags: [] });
  assert.deepEqual(service.patch({ tags: [' a ', 'b'] }), { displayName: 'x', tags: ['a', 'b'] });
  assert.deepEqual(service.patch({ tags: [] }), { displayName: 'x', tags: [] });
  assert.deepEqual(service.patch({ tags: ['1'.repeat(12)] }), { displayName: 'x', tags: ['1'.repeat(12)] });
  assert.deepEqual(service.patch({ tags: ['a', 'b', 'c', 'd', 'e'] }), { displayName: 'x', tags: ['a', 'b', 'c', 'd', 'e'] });
  throwsInvalid(() => service.patch({ tags: ['1'.repeat(13)] }), 'tag too long');
  throwsInvalid(() => service.patch({ tags: [''] }), 'empty tag');
  throwsInvalid(() => service.patch({ tags: ['   '] }), 'blank tag');
  throwsInvalid(() => service.patch({ tags: ['a', ' a '] }), 'duplicate after trim');
  throwsInvalid(() => service.patch({ tags: ['a', 'b', 'c', 'd', 'e', 'f'] }), 'six tags');
  throwsInvalid(() => service.patch({ tags: [1] }), 'numeric tag');
  throwsInvalid(() => service.patch({ tags: ['ok', true] }), 'boolean tag');
  throwsInvalid(() => service.patch({ tags: 'a' }), 'string tags');
  throwsInvalid(() => service.patch({ tags: 5 }), 'numeric tags');
  throwsInvalid(() => service.patch({ tags: {} }), 'object tags');
  const sparse = ['a', , 'b'];
  throwsInvalid(() => service.patch({ tags: sparse }), 'sparse tags');
  assert.deepEqual(service.profile, { displayName: 'x', tags: ['a', 'b', 'c', 'd', 'e'] });
}

// Atomicity: a valid field is not applied when another field is invalid
{
  const service = new ProfileService({ displayName: 'before', tags: ['old'] });
  throwsInvalid(() => service.patch({ displayName: 'after', tags: [''] }), 'mixed invalid');
  assert.deepEqual(service.profile, { displayName: 'before', tags: ['old'] });
}

// Shape validation
{
  const service = new ProfileService({ displayName: 'before', tags: ['old'] });
  for (const bad of [null, undefined, 1, 'x', true, [], ['x'], new Date(), /x/, new (class { constructor() { this.displayName = 'x'; } })()]) {
    throwsInvalid(() => service.patch(bad), `bad input ${String(bad)}`);
  }
  const customProto = Object.create({ displayName: 'x' });
  throwsInvalid(() => service.patch(customProto), 'custom prototype');
  throwsInvalid(() => service.patch({ extra: true }), 'unknown key');
  throwsInvalid(() => service.patch({ displayName: 'x', extra: undefined }), 'unknown undefined key');
  const withSymbol = { displayName: 'x' };
  withSymbol[Symbol('extra')] = 1;
  throwsInvalid(() => service.patch(withSymbol), 'symbol key');
  const withHidden = {};
  Object.defineProperty(withHidden, 'hidden', { value: 1, enumerable: false });
  throwsInvalid(() => service.patch(withHidden), 'non-enumerable key');
  assert.deepEqual(service.profile, { displayName: 'before', tags: ['old'] });
}

// Null-prototype objects are plain enough
{
  const service = new ProfileService({ displayName: 'before', tags: ['old'] });
  const input = Object.assign(Object.create(null), { displayName: ' null proto ', tags: [' t '] });
  assert.deepEqual(service.patch(input), { displayName: 'null proto', tags: ['t'] });
}

// Input is not mutated and caller arrays are not reused
{
  const service = new ProfileService({ displayName: 'before', tags: ['old'] });
  const inputTags = [' a ', 'b'];
  const input = { displayName: '  after  ', tags: inputTags };
  service.patch(input);
  assert.deepEqual(input, { displayName: '  after  ', tags: [' a ', 'b'] });
  assert.notStrictEqual(service.profile.tags, inputTags);
  inputTags.push('c');
  assert.deepEqual(service.profile.tags, ['a', 'b']);
  service.patch({ tags: service.profile.tags });
  assert.notStrictEqual(service.profile.tags, service.profile.tags);
}

// parseProfile directly
{
  assert.deepEqual(parseProfile({}), { displayName: { kind: 'keep' }, tags: { kind: 'keep' } });
  assert.deepEqual(parseProfile({ displayName: null }), { displayName: { kind: 'set', value: null }, tags: { kind: 'keep' } });
  assert.deepEqual(parseProfile({ tags: null }), { displayName: { kind: 'keep' }, tags: { kind: 'set', value: [] } });
  throwsInvalid(() => parseProfile({ unknown: 1 }), 'parse unknown');
}

console.log('contract checks passed');
